            border-bottom: 1px solid #333;
            padding-bottom: 5px;
        }
    </style>
</head>
<body>
    <div class="wrapper">
        <div class="neon-border">
            <div class="inner-content">
                <h1 style="text-align: center; color: var(--yem-red); text-shadow: 0 0 15px var(--yem-red);">TAHER ROYAL SYSTEM <span style="color: var(--yem-gold);">v20.0</span></h1>
                <p style="text-align: center; color: #888; margin-bottom: 20px;">محرك التخمين الخارق، تم تطويره خصيصًا لك يا R_I_Ie!</p>

                <div class="stat-bar">
                    <div class="stat-item"><span class="stat-label">محاولات</span><span id="total-attempts" class="stat-value">0</span></div>
                    <div class="stat-item"><span class="stat-label">ناجح</span><span id="successful-attempts" class="stat-value" style="color: var(--yem-green);">0</span></div>
                    <div class="stat-item"><span class="stat-label">فاشل</span><span id="failed-attempts" class="stat-value" style="color: var(--yem-red);">0</span></div>
                    <div class="stat-item"><span class="stat-label">الحالة</span><span id="status" class="stat-value" style="color: #bbb;">متوقف</span></div>
                </div>

                <div class="nano-display">
                    <p style="color: #888; font-size: 12px; margin-bottom: 5px;">الرمز الحالي قيد التخمين:</p>
                    <div id="active-code">0000 0000 0000 0000</div>
                </div>

                <h3 class="section-title">إعدادات التخمين المتقدمة</h3>

                <div class="input-group">
                    <label for="guess-prefix">بادئة الكروت (مثال: 4567):</label>
                    <input type="text" id="guess-prefix" placeholder="أدخل البادئة (اختياري)">
                </div>
                <div class="input-group">
                    <label for="guess-length">طول الكود المراد تخمينه (بما في ذلك البادئة):</label>
                    <input type="number" id="guess-length" value="16" min="1" max="19" placeholder="طول الكود">
                </div>
                <div class="input-group">
                    <label for="delay-time">حق السرعة (التأخير بين المحاولات بالمللي ثانية):</label>
                    <input type="number" id="delay-time" value="250" min="50" placeholder="مللي ثانية">
                </div>
                <div class="input-group">
                    <label for="burst-limit">حد المحاولات في الدفعة الواحدة (قبل التوقف المؤقت):</label>
                    <input type="number" id="burst-limit" value="100" min="1" placeholder="عدد المحاولات">
                </div>
                <div class="input-group">
                    <label for="target-url">رابط API أو الوجهة المستهدفة للتحقق:</label>
                    <input type="text" id="target-url" value="https://example.com/check_card" placeholder="أدخل رابط التحقق هنا">
                </div>

                <h3 class="section-title">خيارات الحماية المتقدمة</h3>
                <div class="input-group">
                    <label for="proxy-list">قائمة البرو**يات (لكل سطر): <small style="color: #aaa;">(يتطلب إعدادات إضافية في بيئة الخادم أو المتصفح لاستخدامه)</small></label>
                    <textarea id="proxy-list" placeholder="أدخل البرو**يات هنا (اختياري)"></textarea>
                </div>
                <div class="input-group">
                    <label for="user-agent-selection">تغيير User-Agent لمحاكاة متصفحات مختلفة:</label>
                    <select id="user-agent-selection" style="background: #151515; border: 1px solid #333; border-radius: 4px; padding: 8px 12px; color: white; font-size: 13px; width: 100%; font-family: inherit;">
                        <option value="default">افتراضي (Default)</option>
                        <option value="chrome">Chrome (Windows)</option>
                        <option value="firefox">Firefox (Linux)</option>
                        <option value="safari">Safari (Mac)</option>
                        <option value="mobile">Mobile (Android)</option>
                    </select>
                </div>

                <div class="btns-grid">
                    <button class="btn btn-start" onclick="startGuessing()">بدء التخمين 🔥</button>
                    <button class="btn btn-stop" onclick="stopGuessing()">إيقاف التخمين ⛔</button>
                    <button class="btn btn-report" onclick="resetStats()">إعادة تعيين الإحصائيات</button>
                    <button class="btn btn-report" onclick="showAdvancedRepair()">أدوات إصلاح متقدمة</button>
                </div>
            </div>
