                <div class="stat-item"><span class="stat-label">المحاولات</span><span id="count" class="stat-value">0</span></div>
                <div class="stat-item"><span class="stat-label">النسبة</span><span id="percent" class="stat-value">0%</span></div>
                <div class="stat-item"><span class="stat-label">المصيدة</span><span id="wins" class="stat-value">0</span></div>
                <div class="stat-item"><span class="stat-label">الحالة</span><span id="status" class="stat-value" style="color: var(--yem-green);">متوقف</span></div>
            </div>

            <div class="nano-display">
                <p style="font-size: 14px; color: #aaa;">الكرت الحالي</p>
                <span id="active-code">0000000000</span>
            </div>

            <div class="input-group">
                <label for="target">الهدف (URL) <small style="color:#555;">(مثال: https://target.com/check.php)</small></label>
                <input type="text" id="target" value="https://example.com/check.php" placeholder="أدخل رابط الهدف هنا">
            </div>
            <div class="input-group">
                <label for="prefix">بادئة الكرت (اختياري)</label>
                <input type="text" id="prefix" value="" placeholder="مثال: 4567">
