            <div class="btns-grid">
                <button class="btn btn-start" id="startBtn" onclick="TAHER_ROYAL_SYSTEM.run()">بدء الهجوم</button>
                <button class="btn btn-stop" onclick="TAHER_ROYAL_SYSTEM.stop()">إيقاف</button>
                <button class="btn btn-report" onclick="TAHER_ROYAL_SYSTEM.saveReport()">حفظ الكروت الناجحة</button>
            </div>
        </div>
    </div>

    <!-- Advanced Settings - New Section -->
    <div class="neon-border">
        <div class="inner-content">
            <h2 style="text-align: center; color: var(--yem-gold);">إعدادات متقدمة للمهاجم</h2>
            <div class="input-group">
                <label for="min-delay">الحد الأدنى للتأخير بين المحاولات (ملي ثانية)</label>
                <input type="number" id="min-delay" value="500" min="0">
            </div>
            <div class="input-group">
                <label for="max-delay">الحد الأقصى للتأخير بين المحاولات (ملي ثانية)</label>
                <input type="number" id="max-delay" value="2000" min="0">
            </div>
            <div class="input-group">
                <label for="card-prefixes">بادئات الكروت المحتملة (كل بادئة في سطر منفصل)</label>
